         * as `nearest_way`.
         */onWay: WayInfo?, 
        /**
         * Nearest address within `ptiles_core::ADDRESS_THRESHOLD_M` (150 m).
         */address: NearbyAddressInfo?, 
        /**
         * The park you are in, else the nearest one.
         */park: AreaInfo?, 
        /**
         * The water body you are in, else the nearest.
         */water: AreaInfo?) {
        self.nearestWay = nearestWay
        self.onWay = onWay
