public func trailIsDeveloped(trailType: String) -> Bool  {
    return try!  FfiConverterBool.lift(try! rustCall() {
    uniffi_ptiles_ffi_fn_func_trail_is_developed(
        FfiConverterString.lower(trailType),$0
    )
})
